/**
 * Agent skills for this catalog, generated by Google's `@a2ui/agent`
 * `SkillGenerator` (the TypeScript counterpart of the Python SDK's):
 *
 *   a2ui-core/SKILL.md          how to write A2UI in the chosen format
 *   a2ui-playground/SKILL.md    every component and macro with its signature,
 *                               when to use it (the design rules) and worked examples
 *   a2ui-playground/catalog.json  the catalog itself, for an agent that compiles
 *                               Express or validates JSON with an A2UI SDK
 *
 * A selection narrows the skill to some of the components and macros, under a
 * name of its own, with an optional "when to use" note per component. With no
 * selection it covers the whole catalog, as `pnpm skills:export` writes it.
 *
 * Drop the folder into any agent that reads skills (Claude Code, ADK, Gemini
 * CLI), point it at a renderer of this catalog, and it composes the same UI.
 */
import { CatalogConfig, DirectJsonFormat, ExpressFormat, InMemoryCatalogProvider, Skill, SkillGenerator, SkillSet } from "@a2ui/agent";
import { definitions } from "@/a2ui/catalog/definitions";
import type { Category } from "@/a2ui/catalog/definitions/shared";
import { CATALOG_EXAMPLES } from "@/a2ui/catalog/examples";
import { firstSentence } from "@/a2ui/catalog/prompt-trim";
import { MACROS } from "@/a2ui/macros/macros";
import inference from "./inference-catalog.json";

export type SkillFormat = "express" | "json";
export const SKILL_NAME = "a2ui-playground";

type Doc = typeof inference & { components: Record<string, { description?: string }>; $defs: { anyComponent: { oneOf: Array<{ $ref: string }> } } };
const doc = inference as unknown as Doc;

export type SkillGroup = "Gen UI 2.0 standard" | Category | "Macros";
export type SkillComponent = { name: string; group: SkillGroup; description: string };

const MACRO_NAMES = new Set(MACROS.map((m) => m.name));

/** Every component and macro a skill can cover, in catalog order, with the group it belongs to. */
export function skillComponents(): SkillComponent[] {
  const own = definitions as Record<string, { category: Category }>;
  return Object.entries(doc.components).map(([name, c]) => ({
    name,
    group: MACRO_NAMES.has(name) ? "Macros" : own[name] ? own[name].category : "Gen UI 2.0 standard",
    description: firstSentence(c.description ?? ""),
  }));
}

export type SkillSelection = {
  /** The skill's name and folder: lowercase letters, digits and hyphens. */
  name?: string;
  /** The components and macros the skill covers. All of them when left out. */
  components?: string[];
  /** An optional "when to use" note per component. */
  notes?: Record<string, string>;
};

/** A safe skill name: lowercase letters, digits and single hyphens, never the core skill's name. */
export function skillName(name: string | undefined): string {
  const slug = (name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64)
    .replace(/-+$/, "");
  return slug && slug !== "a2ui-core" ? slug : SKILL_NAME;
}

const cleanNote = (note: unknown) => (typeof note === "string" ? note.replace(/\s+/g, " ").trim().slice(0, 400) : "");

/** The catalog narrowed to a selection, with its notes in the instructions. The whole catalog, unchanged, when nothing narrows it. */
function selectCatalog(selection: SkillSelection): Doc {
  const wanted = selection.components ? new Set(selection.components) : undefined;
  const names = Object.keys(doc.components).filter((n) => !wanted || wanted.has(n));
  const notes = names.map((n) => [n, cleanNote(selection.notes?.[n])] as const).filter(([, note]) => note);
  const subset = names.length < Object.keys(doc.components).length;
  if (!subset && !notes.length) return doc;

  const instructions = [
    subset
      ? `## Components in this skill\n\nThis skill covers ${names.length} of the catalog's ${Object.keys(doc.components).length} components: only the ones listed above. If a design rule below names a component that is not listed, use the closest one that is.`
      : "",
    notes.length ? `## When to use which component\n\n${notes.map(([n, note]) => `- ${n}: ${note}`).join("\n")}` : "",
    doc.instructions,
  ].filter(Boolean);
  const kept = new Set(names);
  return {
    ...doc,
    instructions: instructions.join("\n\n"),
    components: Object.fromEntries(names.map((n) => [n, doc.components[n]])),
    $defs: { ...doc.$defs, anyComponent: { ...doc.$defs.anyComponent, oneOf: doc.$defs.anyComponent.oneOf.filter((r) => kept.has(r.$ref.split("/").pop()!)) } },
  } as Doc;
}

/** Worked examples that use only the components in the catalog. */
function examplesFor(selected: Doc) {
  return Object.values(CATALOG_EXAMPLES).filter((messages) =>
    messages.every((m) => {
      const components = ((m.createSurface as { components?: Array<{ component: string }> } | undefined)?.components ?? []) as Array<{ component: string }>;
      return components.every((c) => c.component in selected.components);
    }),
  );
}

export function generateSkills(format: SkillFormat, selection: SkillSelection = {}): Record<string, string> {
  const selected = selectCatalog(selection);
  const name = skillName(selection.name);
  const whole = selected === doc;
  const cat = new CatalogConfig(new InMemoryCatalogProvider(selected as unknown as Record<string, unknown>).load()).catalog;
  const examples = { [doc.catalogId]: examplesFor(selected) } as never;
  const fmt = format === "express" ? new ExpressFormat([cat], { examples }) : new DirectJsonFormat([cat], examples);
  const generator = new SkillGenerator(fmt);
  const set = new SkillSet();
  set.add(generator.generateCoreSkill());
  const formatName = format === "express" ? "Express" : "JSON";
  set.add(
    generator.generateCatalogSkill({
      catalog: cat,
      name,
      description: whole
        ? `Compose UI from the A2UI Playground catalog (CopilotKit Gen UI 2.0 standard components, charts, maps, data views, inputs, domain cards and macros) in A2UI ${formatName}. Use when an answer is better shown than told: dashboards, comparisons, forms, plans, maps.`
        : `Compose UI from ${Object.keys(selected.components).length} components of the A2UI Playground catalog in A2UI ${formatName}. Use when an answer is better shown than told.`,
    }),
  );
  return {
    ...set.toDict(),
    [`${name}/catalog.json`]: `${JSON.stringify(selected, null, 1)}\n`,
  };
}

export type { Skill };
